"use strict";(self.webpackChunkkommander_docs=self.webpackChunkkommander_docs||[]).push([[9867],{9209:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/kommander.github.io/docs/intro","label":"Kommander","docId":"intro","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/why-kommander","label":"Why Kommander?","docId":"why-kommander","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/getting-started","label":"Getting Started","docId":"getting-started","unlisted":false},{"type":"category","label":"Guides","items":[{"type":"link","href":"/kommander.github.io/docs/guides/creating-a-node","label":"Creating A Node","docId":"guides/creating-a-node","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/replicating-logs","label":"Replicating Logs","docId":"guides/replicating-logs","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/heterogeneous-write-coalescing","label":"Heterogeneous Write Coalescing","docId":"guides/heterogeneous-write-coalescing","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/hosting-endpoints","label":"Hosting Endpoints","docId":"guides/hosting-endpoints","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/sample-server","label":"ASP.NET Core Sample Server","docId":"operations/sample-server","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/advanced-replicated-simpledb","label":"Advanced Tutorial: Build A Replicated Key/Value Service","docId":"guides/advanced-replicated-simpledb","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/security-and-authentication","label":"Security And Authentication","docId":"guides/security-and-authentication","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/checkpointing-and-recovery","label":"Checkpointing And Recovery","docId":"guides/checkpointing-and-recovery","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/elastic-partitions","label":"Elastic Partitions","docId":"guides/elastic-partitions","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/replica-placement","label":"Replica Placement","docId":"guides/replica-placement","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/splitting-a-hot-partition","label":"Splitting A Hot Partition","docId":"guides/splitting-a-hot-partition","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/merging-idle-partitions","label":"Merging Idle Partitions","docId":"guides/merging-idle-partitions","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/dynamic-cluster-membership","label":"Dynamic Cluster Membership","docId":"guides/dynamic-cluster-membership","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/system-partition-state-snapshots","label":"System Partition State Snapshots","docId":"guides/system-partition-state-snapshots","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/thread-free-embedded-mode","label":"Thread-Free Embedded Mode","docId":"guides/thread-free-embedded-mode","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Recipes","items":[{"type":"link","href":"/kommander.github.io/docs/recipes","label":"Recipes","docId":"recipes","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/recipes/leader-owned-workers","label":"Leader-Owned Workers","docId":"recipes/leader-owned-workers","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/recipes/replicated-configuration","label":"Replicated Configuration","docId":"recipes/replicated-configuration","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/recipes/idempotent-job-processing","label":"Idempotent Job Processing","docId":"recipes/idempotent-job-processing","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/recipes/partitioned-metadata","label":"Partitioned Metadata","docId":"recipes/partitioned-metadata","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/recipes/durable-workflow-state","label":"Durable Workflow State","docId":"recipes/durable-workflow-state","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/recipes/checkpointed-projections","label":"Checkpointed Projections","docId":"recipes/checkpointed-projections","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/recipes/splitting-hot-tenant-ranges","label":"Splitting Hot Tenant Ranges","docId":"recipes/splitting-hot-tenant-ranges","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/recipes/merging-cooled-partitions","label":"Merging Cooled Partitions","docId":"recipes/merging-cooled-partitions","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Operating Kommander","items":[{"type":"link","href":"/kommander.github.io/docs/internals/metrics-and-diagnostics","label":"Metrics And Diagnostics","docId":"internals/metrics-and-diagnostics","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/partition-load-signals","label":"Partition Load Signals","docId":"guides/partition-load-signals","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/leader-balancing","label":"Automatic Leader Balancing","docId":"operations/leader-balancing","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/partition-scaling","label":"Partition Scaling","docId":"operations/partition-scaling","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/partition-quiescence","label":"Partition Quiescence","docId":"guides/partition-quiescence","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/swim-failure-detection","label":"SWIM Failure Detection","docId":"guides/swim-failure-detection","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/checkpoints-and-compaction","label":"Checkpoints And Compaction","docId":"operations/checkpoints-and-compaction","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/snapshot-installation","label":"Snapshot Installation","docId":"operations/snapshot-installation","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/wal-diagnostics","label":"WAL Diagnostics","docId":"operations/wal-diagnostics","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/wal-commit-durability","label":"WAL Commit Durability","docId":"operations/wal-commit-durability","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/shared-rocksdb-memory","label":"Shared RocksDB Memory","docId":"operations/shared-rocksdb-memory","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Reference","items":[{"type":"link","href":"/kommander.github.io/docs/reference/iraft-api","label":"IRaft API","docId":"reference/iraft-api","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/reference/configuration","label":"Configuration","docId":"reference/configuration","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/reference/adapters","label":"Adapters","docId":"reference/adapters","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Architecture","items":[{"type":"link","href":"/kommander.github.io/docs/architecture/overview","label":"Architecture Overview","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/architecture/raft","label":"Raft In Kommander","docId":"architecture/raft","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/architecture/partitioning","label":"Partitioning","docId":"architecture/partitioning","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/architecture/hybrid-logical-clocks","label":"Hybrid Logical Clocks","docId":"architecture/hybrid-logical-clocks","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Internals & Development","items":[{"type":"link","href":"/kommander.github.io/docs/internals","label":"Internals","docId":"internals","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/internals/runtime","label":"Runtime","docId":"internals/runtime","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/internals/scheduler","label":"Scheduler Internals","docId":"internals/scheduler","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/internals/backpressure-and-admission-control","label":"Backpressure And Admission Control","docId":"internals/backpressure-and-admission-control","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/internals/wal","label":"WAL Internals","docId":"internals/wal","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/internals/leader-election","label":"Leader Election Internals","docId":"internals/leader-election","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/leadership-control","label":"Leadership Control","docId":"operations/leadership-control","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/guides/log-backfill-and-catch-up","label":"Log Backfill And Catch-Up","docId":"guides/log-backfill-and-catch-up","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/transport-batching","label":"Transport Batching","docId":"operations/transport-batching","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/internals/partitions-and-splitting","label":"Partitions And Splitting","docId":"internals/partitions-and-splitting","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/internals/compaction","label":"Compaction Internals","docId":"internals/compaction","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/testing","label":"Testing","docId":"operations/testing","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/operations/deterministic-testing","label":"Deterministic Testing","docId":"operations/deterministic-testing","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Utilities","items":[{"type":"link","href":"/kommander.github.io/docs/utilities/hash-utils","label":"Hash Utilities","docId":"utilities/hash-utils","unlisted":false},{"type":"link","href":"/kommander.github.io/docs/utilities/support-types","label":"Support Types","docId":"utilities/support-types","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"architecture/hybrid-logical-clocks":{"id":"architecture/hybrid-logical-clocks","title":"Hybrid Logical Clocks","description":"Kommander uses hybrid logical clock timestamps as proposal tickets. A hybrid logical clock, or HLC, combines a physical clock reading with a logical counter. The idea comes from the paper Logical Physical Clocks and Consistent Snapshots in Globally Distributed Databases.","sidebar":"tutorialSidebar"},"architecture/overview":{"id":"architecture/overview","title":"Architecture Overview","description":"Kommander is an embedded Raft runtime for .NET services.","sidebar":"tutorialSidebar"},"architecture/partitioning":{"id":"architecture/partitioning","title":"Partitioning","description":"Kommander uses independent Raft partitions. Partition 0 is reserved for replicated system configuration. Application data must use user partitions with ids greater than 0; the first user partition is 1.","sidebar":"tutorialSidebar"},"architecture/raft":{"id":"architecture/raft","title":"Raft In Kommander","description":"Raft is a consensus protocol that helps a cluster maintain a replicated state machine by synchronizing a durable log. A leader receives proposed changes, writes them locally, replicates them to followers, and commits them after a quorum acknowledges the proposal.","sidebar":"tutorialSidebar"},"getting-started":{"id":"getting-started","title":"Getting Started","description":"This page takes you from an empty project to a node that joins a cluster and replicates one command. At the end, you know the parts that every Kommander node needs, and where your own code connects to them. Use it to check your setup. Then continue to the guides to design a real service.","sidebar":"tutorialSidebar"},"guides/advanced-replicated-simpledb":{"id":"guides/advanced-replicated-simpledb","title":"Advanced Tutorial: Build A Replicated Key/Value Service","description":"This tutorial examines Kommander SimpleDB. SimpleDB is a small but complete service with three nodes. It uses ASP.NET Core, Kommander, gRPC, and SQLite.","sidebar":"tutorialSidebar"},"guides/checkpointing-and-recovery":{"id":"guides/checkpointing-and-recovery","title":"Checkpointing And Recovery","description":"A checkpoint gives your application a durable safe point inside the log of a partition.","sidebar":"tutorialSidebar"},"guides/creating-a-node":{"id":"guides/creating-a-node","title":"Creating A Node","description":"A node is one member of a Kommander cluster. In code, a node is one RaftManager instance, and each process in a real cluster usually runs one node. This page shows how to build a node, start it, and stop it. At the end, your process can join a cluster and receive committed entries.","sidebar":"tutorialSidebar"},"guides/dynamic-cluster-membership":{"id":"guides/dynamic-cluster-membership","title":"Dynamic Cluster Membership","description":"Use dynamic membership to grow, shrink, or repair a cluster while it runs. You can add a node for more capacity, remove a node for maintenance, or replace a node that failed. The other nodes keep running, and the quorum stays safe during each change.","sidebar":"tutorialSidebar"},"guides/elastic-partitions":{"id":"guides/elastic-partitions","title":"Elastic Partitions","description":"Elastic partitions let you change the partition layout while the cluster runs. You do not need to know the correct partition count in advance. When one key range gets too hot, you split it. When two ranges go quiet, you merge them.","sidebar":"tutorialSidebar"},"guides/heterogeneous-write-coalescing":{"id":"guides/heterogeneous-write-coalescing","title":"Heterogeneous Write Coalescing","description":"Use ReplicateEntries when one request in your service produces several records of different kinds for the same partition. You write them all with one call. Kommander can put the entries into fewer proposals and fewer replication round trips than separate ReplicateLogs calls. You still get one result for each entry. You do not need to configure anything.","sidebar":"tutorialSidebar"},"guides/hosting-endpoints":{"id":"guides/hosting-endpoints","title":"Hosting Endpoints","description":"Raft nodes send messages to each other all the time: vote requests, heartbeats, and log entries. With a network transport, each node receives these messages through endpoints in its own ASP.NET Core host. Kommander supplies the route map. Your host must expose it.","sidebar":"tutorialSidebar"},"guides/log-backfill-and-catch-up":{"id":"guides/log-backfill-and-catch-up","title":"Log Backfill And Catch-Up","description":"Backfill brings a node that fell behind back up to date, with no manual copy of data. It also lets a new learner catch up before it becomes a voter.","sidebar":"tutorialSidebar"},"guides/merging-idle-partitions":{"id":"guides/merging-idle-partitions","title":"Merging Idle Partitions","description":"Merge two partitions when the cluster has more user partitions than the workload needs.","sidebar":"tutorialSidebar"},"guides/partition-load-signals":{"id":"guides/partition-load-signals","title":"Partition Load Signals","description":"Use these signals to find a partition that is hot or that cannot keep up, before you split it. A request count in your own code is not enough. When the disk reaches its limit, the rate stays flat while the work waits in a queue. These signals show that difference.","sidebar":"tutorialSidebar"},"guides/partition-quiescence":{"id":"guides/partition-quiescence","title":"Partition Quiescence","description":"Partition quiescence reduces the heartbeat traffic of idle partitions.","sidebar":"tutorialSidebar"},"guides/replica-placement":{"id":"guides/replica-placement","title":"Replica Placement","description":"Use replica placement when your cluster grows beyond a few nodes. By default, every voter stores every user partition, so each new node adds work to every partition and widens every quorum. With placement, each partition lives on a fixed number of nodes. A larger cluster then spreads the partitions across more machines, and each write still waits for a small quorum only.","sidebar":"tutorialSidebar"},"guides/replicating-logs":{"id":"guides/replicating-logs","title":"Replicating Logs","description":"Replication is how your service makes a decision durable on more than one node. Your code proposes a command on the partition leader. Kommander stores the command on a quorum of replicas and only then reports success. Every replica of the partition then receives the committed commands in the same order. If the leader fails after the commit, the command is not lost.","sidebar":"tutorialSidebar"},"guides/security-and-authentication":{"id":"guides/security-and-authentication","title":"Security And Authentication","description":"Kommander nodes send Raft messages to each other: votes, heartbeats, and log entries. Transport security makes sure that only members of your cluster can send these messages to a node, and that the traffic uses TLS.","sidebar":"tutorialSidebar"},"guides/splitting-a-hot-partition":{"id":"guides/splitting-a-hot-partition","title":"Splitting A Hot Partition","description":"Split a partition when one user partition does much more work than the other partitions in the cluster.","sidebar":"tutorialSidebar"},"guides/swim-failure-detection":{"id":"guides/swim-failure-detection","title":"SWIM Failure Detection","description":"The failure detector finds nodes that stopped answering. Kommander needs it for two automatic actions: the eviction of a dead member from the roster, and the failover of an idle partition that sends no heartbeats.","sidebar":"tutorialSidebar"},"guides/system-partition-state-snapshots":{"id":"guides/system-partition-state-snapshots","title":"System Partition State Snapshots","description":"Read this page only if your application stores its own cluster-wide state on partition 0 and writes that state as deltas. Most applications keep their data on user partitions and do not need this page.","sidebar":"tutorialSidebar"},"guides/thread-free-embedded-mode":{"id":"guides/thread-free-embedded-mode","title":"Thread-Free Embedded Mode","description":"Kommander can run in hosts that cannot create OS threads. The main target is single-threaded .NET WebAssembly, such as a browser tab or a Node.js-hosted browser-wasm app with WasmEnableThreads disabled.","sidebar":"tutorialSidebar"},"internals":{"id":"internals","title":"Internals","description":"This section explains how Kommander works below the public API. It is meant for developers who want to understand the runtime before operating it, debugging it, or contributing to it.","sidebar":"tutorialSidebar"},"internals/backpressure-and-admission-control":{"id":"internals/backpressure-and-admission-control","title":"Backpressure And Admission Control","description":"Kommander uses several layers of backpressure and admission control to keep one hot partition or a burst of client traffic from overwhelming the runtime.","sidebar":"tutorialSidebar"},"internals/compaction":{"id":"internals/compaction","title":"Compaction Internals","description":"Compaction removes old WAL entries that are older than a checkpoint. The WAL is the write-ahead log. Compaction keeps the disk use of each node from growing without limit.","sidebar":"tutorialSidebar"},"internals/leader-election":{"id":"internals/leader-election","title":"Leader Election Internals","description":"Each partition elects its own leader. This page explains how Kommander runs that election: the timeouts, the pre-vote round, and the repair checks that a new leader runs before it serves the application.","sidebar":"tutorialSidebar"},"internals/metrics-and-diagnostics":{"id":"internals/metrics-and-diagnostics","title":"Metrics And Diagnostics","description":"Use metrics and logs to find out why a cluster is slow or unstable. Kommander reports what happens inside each partition: queue depths, operation latency, WAL batches, elections, snapshots, backfill, and leader moves. With this data, you can find the cause of a problem instead of guessing.","sidebar":"tutorialSidebar"},"internals/partitions-and-splitting":{"id":"internals/partitions-and-splitting","title":"Partitions And Splitting","description":"Partitions divide the keyspace into independent Raft groups. This page explains how Kommander maps a key to a partition, and how every node keeps the same partition map.","sidebar":"tutorialSidebar"},"internals/runtime":{"id":"internals/runtime","title":"Runtime","description":"Kommander\'s runtime is process-level coordination plus per-partition ownership. One RaftManager object coordinates the process. Each partition owns its own Raft state.","sidebar":"tutorialSidebar"},"internals/scheduler":{"id":"internals/scheduler","title":"Scheduler Internals","description":"Kommander separates state-machine execution from blocking storage work. Storage calls then do not block the Raft state machine of a partition, and one busy partition cannot starve the others.","sidebar":"tutorialSidebar"},"internals/wal":{"id":"internals/wal","title":"WAL Internals","description":"The write-ahead log, or WAL, is how Kommander remembers Raft log entries across restarts. After a restart, a node reads its WAL to rebuild the Raft state of each partition.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Kommander","description":"Kommander is an open-source distributed consensus library for C#/.NET. It helps several running processes agree on the same ordered stream of changes, even when individual nodes restart, lose network connectivity, or stop responding.","sidebar":"tutorialSidebar"},"operations/checkpoints-and-compaction":{"id":"operations/checkpoints-and-compaction","title":"Checkpoints And Compaction","description":"Checkpoints and compaction keep the WAL from growing without limit. The WAL is the write-ahead log. Without compaction, each node keeps every log entry of every partition. Disk use then grows for as long as the cluster runs.","sidebar":"tutorialSidebar"},"operations/deterministic-testing":{"id":"operations/deterministic-testing","title":"Deterministic Testing","description":"Use the deterministic simulation tests when a consensus bug depends on timing and you cannot reproduce it on purpose. A normal multi-process test finds such a bug only by chance. The simulation tests make the failure repeatable: a failing run leaves a plan file, and you can replay that plan, measure how often it fails, and shrink it to a small schedule.","sidebar":"tutorialSidebar"},"operations/leader-balancing":{"id":"operations/leader-balancing","title":"Automatic Leader Balancing","description":"Each Kommander user partition is an independent Raft group with its own leader. Each group elects its leader independently. Therefore, one node can lead many more partitions than its peers. The busiest partitions can also collect on one node, even with similar leader counts.","sidebar":"tutorialSidebar"},"operations/leadership-control":{"id":"operations/leadership-control","title":"Leadership Control","description":"Use the APIs on this page when your code must know which node leads a partition, or when a test must move leadership at a known moment.","sidebar":"tutorialSidebar"},"operations/partition-scaling":{"id":"operations/partition-scaling","title":"Partition Scaling","description":"Read this page when one node hosts many partitions, for example thousands, and most of them are idle at any moment. Without care, each partition costs a thread and frequent timer work, even when it does nothing. Kommander removes most of that idle cost. The thread use and the CPU use then follow the active partitions, not the total partition count.","sidebar":"tutorialSidebar"},"operations/sample-server":{"id":"operations/sample-server","title":"ASP.NET Core Sample Server","description":"Kommander.Server is a ready-made ASP.NET Core host in the Kommander repository. Use it to run a Kommander cluster before you write any host code of your own. Start several instances on your machine, and you can watch leader election, replication, and failover.","sidebar":"tutorialSidebar"},"operations/shared-rocksdb-memory":{"id":"operations/shared-rocksdb-memory","title":"Shared RocksDB Memory","description":"Some applications embed Kommander and also use RocksDB for their own local data. Kahuna is a typical example. One process can host a Kommander RocksDbWAL and an application RocksDB database. The WAL is the write-ahead log.","sidebar":"tutorialSidebar"},"operations/snapshot-installation":{"id":"operations/snapshot-installation","title":"Snapshot Installation","description":"Snapshot installation repairs a node that is too far behind to catch up from the log. Without it, a node that was offline during a compaction cannot catch up. A new node that joins after a compaction also cannot catch up.","sidebar":"tutorialSidebar"},"operations/testing":{"id":"operations/testing","title":"Testing","description":"This page is for contributors. Run the Kommander test suite when you change Kommander itself, when you review a pull request, or when you want to reproduce a bug report against the source. The suite checks Raft safety rules, the schedulers, the WAL adapters, and failure scenarios on real in-process clusters.","sidebar":"tutorialSidebar"},"operations/transport-batching":{"id":"operations/transport-batching","title":"Transport Batching","description":"Transport batching reduces the network cost of Raft traffic. Kommander puts many small Raft messages for one peer into a single transport request. The nodes then send fewer requests and spend less time on the overhead of each message. The gain is largest under a heavy write load.","sidebar":"tutorialSidebar"},"operations/wal-commit-durability":{"id":"operations/wal-commit-durability","title":"WAL Commit Durability","description":"Read this page when the write latency on durable storage is too high, or when you must know exactly when a write is safe after a crash. On RocksDB or SQLite, the disk sync can be the largest part of the write latency. Kommander has settings that reduce that cost without weakening the Raft durability rule.","sidebar":"tutorialSidebar"},"operations/wal-diagnostics":{"id":"operations/wal-diagnostics","title":"WAL Diagnostics","description":"Use the tools on this page when you suspect that storage limits your cluster, or when you must prove that a WAL change helps. The WAL is the write-ahead log. A write commits only after a quorum of replicas stores it in their WAL, so slow disks make slow writes.","sidebar":"tutorialSidebar"},"recipes":{"id":"recipes","title":"Recipes","description":"Kommander gives applications a replicated log, partition leadership, and callbacks for applying committed entries. These recipes show practical ways to use those building blocks in real systems.","sidebar":"tutorialSidebar"},"recipes/checkpointed-projections":{"id":"recipes/checkpointed-projections","title":"Checkpointed Projections","description":"Use Kommander checkpoints when your projection can always be rebuilt from the log, but replay time starts becoming a real operational cost.","sidebar":"tutorialSidebar"},"recipes/durable-workflow-state":{"id":"recipes/durable-workflow-state","title":"Durable Workflow State","description":"Use Kommander to replicate workflow decisions so a process can recover and continue after crashes.","sidebar":"tutorialSidebar"},"recipes/idempotent-job-processing":{"id":"recipes/idempotent-job-processing","title":"Idempotent Job Processing","description":"Use Kommander to make job state transitions explicit before workers perform side effects.","sidebar":"tutorialSidebar"},"recipes/leader-owned-workers":{"id":"recipes/leader-owned-workers","title":"Leader-Owned Workers","description":"Use Kommander when a cluster should have exactly one active coordinator for a shard of work, while still allowing another node to take over after failure.","sidebar":"tutorialSidebar"},"recipes/merging-cooled-partitions":{"id":"recipes/merging-cooled-partitions","title":"Merging Cooled Partitions","description":"Use partition merges when traffic has cooled down and the cluster is carrying more user partitions than it needs.","sidebar":"tutorialSidebar"},"recipes/partitioned-metadata":{"id":"recipes/partitioned-metadata","title":"Partitioned Metadata","description":"Use Kommander to build metadata services where each tenant, resource, or namespace maps to a Raft partition.","sidebar":"tutorialSidebar"},"recipes/replicated-configuration":{"id":"recipes/replicated-configuration","title":"Replicated Configuration","description":"Use Kommander to replicate operational configuration changes across all nodes in a service.","sidebar":"tutorialSidebar"},"recipes/splitting-hot-tenant-ranges":{"id":"recipes/splitting-hot-tenant-ranges","title":"Splitting Hot Tenant Ranges","description":"Use partition splits when one tenant, customer segment, or key range becomes much hotter than the rest of the cluster.","sidebar":"tutorialSidebar"},"reference/adapters":{"id":"reference/adapters","title":"Adapters","description":"An adapter connects Kommander to one part of your environment. Kommander uses three kinds of adapter:","sidebar":"tutorialSidebar"},"reference/configuration":{"id":"reference/configuration","title":"Configuration","description":"Use this page to look up a setting of RaftConfiguration. You do not need to read it from top to bottom. A new node needs only a few settings. The Getting Started example sets only NodeName, NodeId, Host, Port, and InitialPartitions, and keeps the defaults for everything else.","sidebar":"tutorialSidebar"},"reference/iraft-api":{"id":"reference/iraft-api","title":"IRaft API","description":"IRaft is the interface that your application uses to work with Kommander. RaftManager implements it. Use this page to find a member and to check its exact behavior: its parameters, its return values, and its status values.","sidebar":"tutorialSidebar"},"utilities/hash-utils":{"id":"utilities/hash-utils","title":"Hash Utilities","description":"Use HashUtils when your service needs a hash that is the same in every process. The default .NET string.GetHashCode gives a different value in each process, so two nodes can disagree about where a key belongs. The HashUtils functions give the same value in every process and after every restart.","sidebar":"tutorialSidebar"},"utilities/support-types":{"id":"utilities/support-types","title":"Support Types","description":"This page lists public helper types. You meet most of them as parameter types or return types of the elastic partition APIs, so you read about them when you split, merge, or place partitions. The other types are general helpers that Kommander uses internally. You can use them in your own code, but you do not need them to use Kommander.","sidebar":"tutorialSidebar"},"why-kommander":{"id":"why-kommander","title":"Why Kommander?","description":"Kommander is for .NET applications that need several processes to agree on important decisions and continue safely when a node fails.","sidebar":"tutorialSidebar"}}}}')}}]);